"""Turn evaluation results (run.py) into a Markdown report with a verdict per Phase 5 test."""

from __future__ import annotations


def _ci(c: dict, pct: bool = True) -> str:
    if not c or c.get("value") is None:
        return "–"
    f = (lambda x: f"{x * 100:.1f}%") if pct else (lambda x: f"{x:+.2f}")
    lo, hi = c["ci95"]
    return f"{f(c['value'])} [{f(lo)}, {f(hi)}]"


def _pct(x):
    return "–" if x is None else f"{x * 100:.1f}%"


def build(res: dict, repro: bool | None = None) -> str:
    L = ["# Group Pulse: Phase 5 evaluation", "",
         "Generated by `python -m grouppulse.evaluation`. Brackets are bootstrap 95% intervals over meetings "
         f"({res['settings']['bootstrap']}). Ground truth for dominance is AMI speaking time, used for scoring only.", ""]
    verdicts = []

    g = res.get("E1_gaze_idiap")
    if g:
        L += ["## E1 Gaze-target accuracy (T1.5, target 70%)", "",
              f"Idiap, each meeting predicted by a model fitted only on other meeting series ({', '.join(g['series'])}).", "",
              "| Meeting | Accuracy | Always-most-common baseline | Labelled frames |", "| --- | --- | --- | --- |"]
        L += [f"| {x['meeting']} | {_pct(x['accuracy'])} | {_pct(x['majority_baseline'])} | {x['labelled_frames']} |" for x in g["per_meeting"]]
        L += ["", f"**Mean: {_ci(g['mean_accuracy'])}** against {_ci(g['mean_majority_baseline'])} for the baseline.", ""]
        verdicts.append(("T1.5 gaze target ≥ 70%", g["mean_accuracy"]["value"] >= 0.7, _ci(g["mean_accuracy"])))
    e = res.get("E1_gaze_edinburgh")
    if e:
        L += [f"Edinburgh, ES2008a halves: " + ", ".join(f"{x['split']} {_pct(x['accuracy'])}" for x in e["per_split"])
              + f" (mean {_pct(e['mean_accuracy'])}; one group of people only).", ""]

    for site in ("idiap", "edinburgh"):
        d = res.get(f"E2_dominance_{site}")
        if not d:
            continue
        s = d["summary"]
        L += [f"## E2 Dominance vs speaking time, {site.title()} (T5.1)", "",
              "| Method | Top-1 (most talkative found) | Mean rank correlation |", "| --- | --- | --- |"]
        names = {"gaze_pred": "Attention received, predicted gaze", "gaze_true": "Attention received, AMI true gaze (upper bound)",
                 "seat_baseline": "Seat baseline (seat's talkativeness in other meetings)"}
        for k, name in names.items():
            if k in s:
                L.append(f"| {name} | {_ci(s[k]['top1'])} | {_ci(s[k]['mean_rank_corr'], pct=False)} |")
        L += [f"| Random | {_pct(s['random']['top1'])} | +0.00 |", ""]
        L += ["| Meeting | Most talkative | Predicted gaze | True gaze | Seat baseline |", "| --- | --- | --- | --- | --- |"]
        for x in d["per_meeting"]:
            cell = lambda k: (f"{x[k]['order'][0]} {'hit' if x[k]['top1'] else 'miss'}, ρ {x[k]['rho']:+.2f}") if k in x else "–"  # noqa: E731
            L.append(f"| {x['meeting']} | {x['truth'][0]} | {cell('gaze_pred')} | {cell('gaze_true')} | {cell('seat_baseline')} |")
        L.append("")
        if "gaze_pred" in s:
            beat = s["gaze_pred"]["mean_rank_corr"]["value"] > s["seat_baseline"]["mean_rank_corr"]["value"]
            verdicts.append((f"T5.1 dominance beats seat baseline ({site})", beat,
                             f"ρ {s['gaze_pred']['mean_rank_corr']['value']:+.2f} vs {s['seat_baseline']['mean_rank_corr']['value']:+.2f}"))

    a = res.get("E3_ablation_edinburgh")
    if a:
        L += ["## E3 Ablation: gaze vs orientation (T5.3)", "", f"Edinburgh meetings with torso data. {a['note']}.", "",
              "| Variant | Top-1 | Mean rank correlation |", "| --- | --- | --- |"]
        L += [f"| {v} | {_ci(c['top1'])} | {_ci(c['mean_rank_corr'], pct=False)} |" for v, c in a["summary"].items()]
        L.append("")
        verdicts.append(("T5.3 ablation table produced", True, f"{len(a['per_meeting'])} meetings"))

    d = res.get("E4_disengagement_idiap")
    if d:
        L += ["## E4 Disengagement (T5.2, target F1 ≥ 0.6)", "", f"{d['note']}.", "",
              "| Meeting | Scored windows | Disengaged (truth) | Precision | Recall | F1 | Engagement r |",
              "| --- | --- | --- | --- | --- | --- | --- |"]
        L += [f"| {x['meeting']} | {x['scored_windows']} | {x['true_positive_windows']} | {_pct(x['precision'])} | "
              f"{_pct(x['recall'])} | {_pct(x['f1'])} | {x['engagement_r']:+.2f} |" for x in d["per_meeting"]]
        L += ["", f"**Pooled F1: {_ci(d['pooled_f1'])}**. Correlation of 10 s window engagement, predicted vs true gaze: "
              f"{_ci(d.get('mean_engagement_r'), pct=False)}. Disengaged spells (≥ 30 s) are rare (a few percent of windows), "
              "so F1 swings on a handful of windows; the correlation shows how well engagement is tracked overall.", ""]
        verdicts.append(("T5.2 disengagement F1 ≥ 0.6 (proxy truth)", d["pooled_f1"]["value"] >= 0.6, _ci(d["pooled_f1"])))

    if repro is not None:
        verdicts.append(("T5.4 reproducible (two runs, identical output)", repro, "byte-identical JSON" if repro else "outputs differ"))
    verdicts.append(("T5.5 confidence intervals reported", True, "bootstrap over meetings"))

    head = ["## Verdicts", "", "| Test | Result | Evidence |", "| --- | --- | --- |"]
    head += [f"| {name} | {'Pass' if ok else '**Fail**'} | {ev} |" for name, ok, ev in verdicts]
    return "\n".join(L[:4] + head + [""] + L[4:])
